mapper.select:
select 
from cache_message_outbox
where (
    (
        status in

            #{status}

        and available_time <= #{now}
    )
    or
    (
        status = 1
        and update_time <= #{processingExpireTime}
    )
)
order by id asc
limit #{limit}

mapper.update:
update cache_message_outbox
set status = 1,
    update_time = #{updateTime}
where id = #{id}
  and status in

    #{status}

mapper.delete:
delete from cache_message_outbox
where status = 2
  and sent_time is not null
  and sent_time < #{beforeTime}
limit #{limit}
